 * Sorts edges by weight, breaking ties by the first endpoint and then the
 * second.
 * @param {Array<[number, number, number]>} edges Edges to sort.
 * @returns {Array<[number, number, number]>} New, sorted array.
 */
function sortedEdges(edges) {
  return [...edges].sort((a, b) => {
    if (a[2] !== b[2]) return a[2] - b[2];
    if (a[0] !== b[0]) return a[0] - b[0];
    return a[1] - b[1];
  });
}

